<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}$page_title='Services & tarifs';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo=db();$pdo->beginTransaction();try{$nom=trim($_POST['nom']);$code='SRV-'.strtoupper(bin2hex(random_bytes(3)));$pdo->prepare("INSERT INTO services(code,nom,description) VALUES(?,?,?)")->execute([$code,$nom,trim($_POST['description'])]);$serviceId=(int)db_last_insert_id($pdo,'services');$types=$pdo->query("SELECT id FROM types_articles WHERE actif=1")->fetchAll(PDO::FETCH_COLUMN);$tarif=$pdo->prepare("INSERT INTO tarifs(service_id,type_article_id,prix,cout_estime,date_effet) VALUES(?,?,?,?,CURRENT_DATE)");foreach($types as $typeId){$tarif->execute([$serviceId,(int)$typeId,max(0,(float)$_POST['prix']),max(0,(float)$_POST['cout_estime'])]);}$pdo->commit();flash('Service ajouté.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('services.php');}
$rows=db()->query("SELECT s.id,s.code,s.nom,s.description,s.actif AS active,t.prix,t.cout_estime,ta.nom AS type_article FROM services s LEFT JOIN tarifs t ON t.service_id=s.id AND t.date_effet=(SELECT MAX(t2.date_effet) FROM tarifs t2 WHERE t2.service_id=s.id AND t2.type_article_id=t.type_article_id AND t2.date_effet<=CURRENT_DATE) LEFT JOIN types_articles ta ON ta.id=t.type_article_id ORDER BY s.id DESC,ta.nom")->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Ajouter une prestation</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nom</label><input name="nom" required></div><div class="field"><label>Prix client (FCFA)</label><input type="number" min="0" name="prix" required></div><div class="field"><label>Coût estimé (FCFA)</label><input type="number" min="0" name="cout_estime" value="0" required><small>Produits, eau, électricité et main-d’œuvre estimés par pièce.</small></div><div class="field full"><label>Description</label><input name="description"></div><div><button class="btn">Ajouter</button></div></form></div><div class="panel"><h2>Tarifs disponibles</h2><table><thead><tr><th>Prestation</th><th>Prix client</th><th>Coût estimé</th><th>Marge brute</th><th>Description</th><th>État</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nom'])?> · <?=e($r['type_article']??'—')?></td><td><?=money($r['prix']??0)?></td><td><?=money($r['cout_estime'])?></td><td><b><?=money($r['prix']-$r['cout_estime'])?></b></td><td><?=e($r['description'])?></td><td><?=$r['active']?'Actif':'Inactif'?></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>
